access-gates:
import { BodyText, Button, CardTitle, GdsAccessGate, GdsStack, resolveGdsAccessState } from '@sovereignsquad/gds-core';
import type { GdsAccessGateAction } from '@sovereignsquad/gds-core';
import { useEffect, useState } from 'react';

function AccessGatePlaygroundDemo() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isSigningIn, setIsSigningIn] = useState(false);

  useEffect(() => {
    if (!isSigningIn) {
      return;
    }

    const timer = setTimeout(() => {
      setIsAuthenticated(true);
      setIsSigningIn(false);
    }, 500);

    return () => clearTimeout(timer);
  }, [isSigningIn]);

  const baseContract = resolveGdsAccessState({
    gateId: 'article-paywall-demo',
    session: isSigningIn
      ? { status: 'loading' }
      : isAuthenticated
        ? { status: 'authenticated', subjectId: 'demo-user' }
        : { status: 'anonymous' },
    entitlement: isAuthenticated ? { allowed: true, label: 'Member' } : undefined,
  });

  const contract = isSigningIn
    ? {
        ...baseContract,
        state: 'unlocking' as const,
        reason: baseContract.reason ?? 'login-required',
        title: 'Signing in',
        description: 'Authenticating your sample identity and role to unlock premium content.',
      }
    : baseContract;

  const previewTitle = isAuthenticated ? 'Member unlocked' : 'Article preview';

  const beginSignIn = () => {
    if (isSigningIn || isAuthenticated) {
      return;
    }

    setIsSigningIn(true);
  };

  const beginSignOut = () => {
    setIsSigningIn(false);
    setIsAuthenticated(false);
  };

  const handleAction = (action: GdsAccessGateAction) => {
    if (action.kind === 'sign-in' || action.kind === 'sign-up') {
      beginSignIn();
    }
  };

  return (
    <GdsStack gap="sm">
      <GdsAccessGate
        {...contract}
        protectedContentPolicy="never-render-while-locked"
        teaserLabel="Article preview"
        entitlementLabel="Member"
        preview={
          <GdsStack gap="sm">
            <CardTitle order={4}>{previewTitle}</CardTitle>
            <BodyText>
              Use this boundary when a page can show summary content while protecting premium or private detail.
              The protected member section is never mounted until unlocked.
            </BodyText>
          </GdsStack>
        }
        protectedContent={() => (
          <GdsStack gap="sm">
            <CardTitle order={4}>Protected member-only article body</CardTitle>
            <BodyText>This content only mounts after the access state is unlocked.</BodyText>
          </GdsStack>
        )}
        onAction={handleAction}
      />
      <GdsStack gap="sm">
        <Button variant="default" size="compact-sm" type="button" onClick={beginSignIn} disabled={isSigningIn || isAuthenticated}>
          Click to login
        </Button>
        {isAuthenticated ? (
          <>
            {' '}
            <Button variant="default" size="compact-sm" type="button" onClick={beginSignOut}>
              Sign out
            </Button>
          </>
        ) : null}
      </GdsStack>
    </GdsStack>
  );
}

