import { GdsMapBasemapWash, GdsMapFilterRail, GdsMapPinPreviewCard, GdsStack, MapPanel, SemanticButton, gdsBadgeAccentColors } from '@sovereignsquad/gds-core';
import { GdsMap } from '@sovereignsquad/gds-core/map';
import { useState } from 'react';

const MAP_PIN_MARKERS: Array<{
  id: string;
  position: { lat: number; lng: number };
  accent: keyof typeof gdsBadgeAccentColors;
  icon: 'Location' | 'Habit' | 'Message' | 'Verify';
  label: string;
}> = [
  { id: 'cafe', position: { lat: 51.5079, lng: -0.0877 }, accent: 'ocean', icon: 'Location', label: 'Bankside café' },
  { id: 'library', position: { lat: 51.5133, lng: -0.0886 }, accent: 'teal', icon: 'Habit', label: 'Barbican library' },
  { id: 'gallery', position: { lat: 51.5031, lng: -0.1195 }, accent: 'grape', icon: 'Message', label: 'South Bank gallery' },
  { id: 'coworking', position: { lat: 51.5014, lng: -0.0993 }, accent: 'forest', icon: 'Verify', label: 'Borough co-working' },
];

const MAP_PIN_DETAILS: Record<string, {
  category: string; categoryId: string; neighbourhood: string; summary: string;
  audience: string; priceEstimate?: string; lastChecked?: string;
  verified?: boolean; categoryIcon: 'Location' | 'Habit' | 'Message' | 'Verify';
}> = {
  // Four different domains, deliberately: the pin system is domain-agnostic.
  cafe: { category: 'Coffee', categoryId: 'coffee', neighbourhood: 'Bankside', summary: 'Independent roastery with long tables and reliable wifi.', audience: 'All ages', priceEstimate: '~\u00a34 / visit', lastChecked: 'Checked last week', categoryIcon: 'Location' },
  library: { category: 'Reading', categoryId: 'reading', neighbourhood: 'Barbican', summary: 'Public library with quiet study floors and weekly author talks.', audience: 'All ages', priceEstimate: 'Free entry', lastChecked: 'Checked this month', categoryIcon: 'Habit' },
  gallery: { category: 'Art', categoryId: 'art', neighbourhood: 'South Bank', summary: 'Riverside gallery with rotating exhibitions and guided tours.', audience: '12+', categoryIcon: 'Message' },
  coworking: { category: 'Co-working', categoryId: 'coworking', neighbourhood: 'Borough', summary: 'Hot desks, bookable meeting rooms and a shared kitchen.', audience: '18+', priceEstimate: '~\u00a3180 / month', lastChecked: 'Checked last week', verified: true, categoryIcon: 'Verify' },
};

function MapSurfaceDemo() {
  // Rail counts and preview card both derive from the same markers the map renders.
  const [activityFilter, setActivityFilter] = useState<string | null>(null);
  const [selectedPinId, setSelectedPinId] = useState<string | undefined>(undefined);
  const [savedPins, setSavedPins] = useState<Record<string, boolean>>({});

  const visibleMarkers = MAP_PIN_MARKERS.filter(
    (pin) => activityFilter === null || MAP_PIN_DETAILS[pin.id].categoryId === activityFilter,
  );
  const activities = [...new Set(MAP_PIN_MARKERS.map((pin) => MAP_PIN_DETAILS[pin.id].categoryId))];
  const railOptions = activities.map((activityId) => ({
    id: activityId,
    label: MAP_PIN_DETAILS[MAP_PIN_MARKERS.find((pin) => MAP_PIN_DETAILS[pin.id].categoryId === activityId)!.id].category,
    count: MAP_PIN_MARKERS.filter((pin) => MAP_PIN_DETAILS[pin.id].categoryId === activityId).length,
  }));

  return (
    <MapPanel
      title="Nearby places"
      description="Real OpenStreetMap tiles via GdsMap, composed under GdsMapBasemapWash — the tiles desaturate and take a tint of the active theme's canvas colour, so the basemap reads as part of the page rather than a foreign surface. The filter rail's counts come from the same markers the map renders, and selecting a pin opens its preview card. Tiles, markers and the ODbL credit are all governed, and switching the theme above re-initialises the map because Leaflet holds imperative DOM the CSS cascade cannot reach."
      minHeight={320}
      renderMap={() => (
        <GdsStack gap="sm">
          <GdsMapFilterRail
            ariaLabel="Filter places by category"
            options={railOptions}
            value={activityFilter}
            onChange={(next) => {
              setActivityFilter(next);
              setSelectedPinId(undefined);
            }}
          />
          <GdsMapBasemapWash>
            <GdsMap
              label="Nearby places"
              height="320px"
              markers={visibleMarkers.map((pin) => ({
                id: pin.id,
                position: pin.position,
                accent: pin.accent,
                label: pin.label,
              }))}
              selectedMarkerId={selectedPinId}
              onMarkerSelect={(markerId) => setSelectedPinId((current) => (current === markerId ? undefined : markerId))}
              defaultViewport={{ center: { lat: 51.5074, lng: -0.0965 }, zoom: 13 }}
              renderMarkerPreview={(markerId) => {
                const pin = MAP_PIN_MARKERS.find((entry) => entry.id === markerId);
                const detail = MAP_PIN_DETAILS[markerId];
                if (!pin || !detail) return null;
                return (
                  <GdsMapPinPreviewCard
                    title={pin.label}
                    category={detail.category}
                    neighbourhood={detail.neighbourhood}
                    summary={detail.summary}
                    audience={detail.audience}
                    trust={detail.verified ? { variant: 'validation', label: 'Verified provider' } : undefined}
                    priceEstimate={detail.priceEstimate}
                    lastChecked={detail.lastChecked}
                    thumbnailSeed={pin.id}
                    categories={[{ key: detail.categoryId, label: detail.category, icon: detail.categoryIcon }]}
                    primaryAction={<SemanticButton action="preview" fullWidth />}
                    saved={Boolean(savedPins[pin.id])}
                    saveLabel={`Save ${pin.label}`}
                    unsaveLabel={`Remove ${pin.label} from saved`}
                    onSaveChange={(next) => setSavedPins((current) => ({ ...current, [pin.id]: next }))}
                    onClose={() => setSelectedPinId(undefined)}
                    closeLabel={`Close ${pin.label} preview`}
                  />
                );
              }}
            />
          </GdsMapBasemapWash>
        </GdsStack>
      )}
    />
  );
}

