import { BannerNotice, GdsInline, GdsNotificationBell, GdsNotificationProvider, GdsStack, GdsToastViewport, InlineAlert, InlineText, NotificationCenter, SectionPanel, Select, createGdsNotificationId, useGdsNotifications } from '@sovereignsquad/gds-core';
import { useState } from 'react';

function ToastPositionDemo() {
  const [position, setPosition] = useState<'top-start' | 'top-end' | 'bottom-start' | 'bottom-end'>('bottom-end');
  return (
    <>
      <Select
        label="Toast position"
        description="Where GdsToastViewport anchors the toast stack. Trigger a toast with the bell above."
        value={position}
        allowDeselect={false}
        onChange={(value) => { if (value) setPosition(value as typeof position); }}
        data={[
          { value: 'top-start', label: 'Top, start edge' },
          { value: 'top-end', label: 'Top, end edge' },
          { value: 'bottom-start', label: 'Bottom, start edge' },
          { value: 'bottom-end', label: 'Bottom, end edge' },
        ]}
      />
      <GdsToastViewport position={position} />
    </>
  );
}

function NotificationBellDemo() {
  const { notifications, notify, clear } = useGdsNotifications();
  const unread = notifications.length > 0;
  return (
    <SectionPanel
      title="Notification bell"
      description="GdsNotificationBell is the trigger affordance for the notification family — a bell with an unread dot, no panel of its own. Unread here is derived from useGdsNotifications().notifications.length > 0, exactly as a header/topbar consumer would derive it."
    >
      <GdsInline gap="lg" align="center">
        <GdsNotificationBell
          unread={unread}
          onClick={() => {
            if (unread) {
              clear();
            } else {
              notify({ id: createGdsNotificationId('bell-demo'), title: 'New activity added nearby', severity: 'info' });
            }
          }}
        />
        <InlineText>{unread ? `${notifications.length} unread — click the bell to clear` : 'No unread — click the bell to add one'}</InlineText>
      </GdsInline>
    </SectionPanel>
  );
}

<GdsNotificationProvider>
  <SectionPanel title="Notification surface" description="Notifications remain contextual, actionable, and explicit.">
    <GdsStack gap="sm">
      <NotificationBellDemo />
      <br />
      <BannerNotice
        eyebrow="Service status"
        severity="warning"
        title="One partner connector is degraded"
        message="Background sync is delayed. Critical failures are still shown inline as well."
      />
      <br />
      <InlineAlert
        severity="info"
        title="Publishing queue active"
        message="New items will appear once validation completes."
      />
      <br />
      <NotificationCenter />
      <ToastPositionDemo />
    </GdsStack>
  </SectionPanel>
</GdsNotificationProvider>

